class EventEmitter {
  constructor() { this.events = {}; }
  on(event, fn) {
    (this.events[event] = this.events[event] || []).push(fn);
  }
  emit(event, data) {
    (this.events[event] || []).forEach(fn => fn(data));
  }
}
const emitter = new EventEmitter();
emitter.on('test', (d) => console.log(d));
emitter.emit('test', 'emitted');
